package io.coolbox.distributed;
import com.sun.jna.Pointer;import com.sun.jna.ptr.DoubleByReference;import com.sun.jna.ptr.LongByReference;import io.coolbox.internal.ErrorBuffer;import io.coolbox.internal.Matrices;
/** Dataset utilities (Python: {@code distributed.partition_data} and {@code compute_distributed_accuracy}). */
public final class Distributed {private static final DistributedNative N=DistributedNative.INSTANCE;private Distributed(){}
 public static double[][][] partitionData(double[][] data,int worldSize){int cols=Matrices.columns(data);var rows=new LongByReference();var outCols=new LongByReference();ErrorBuffer e=new ErrorBuffer();Pointer p=N.coolbox_dist_partition_data(Matrices.flatten(data),data.length,cols,worldSize,rows,outCols,e.pointer(),e.capacity());double[][] flat=Matrices.takeMatrix(NativeChecks.pointer(p,e),rows.getValue(),outCols.getValue());double[][][] parts=new double[worldSize][][];try(DataPartitioner partitioner=new DataPartitioner(data.length,worldSize)){int offset=0;for(int rank=0;rank<worldSize;rank++){int n=Math.toIntExact(partitioner.partitionSize(rank));parts[rank]=new double[n][cols];for(int i=0;i<n;i++)parts[rank][i]=flat[offset++];}}return parts;}
 public static double computeDistributedAccuracy(double[][] predictions,double[][] labels,DistributedContext context){int pc=Matrices.columns(predictions),lc=Matrices.columns(labels);var out=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_dist_compute_accuracy(Matrices.flatten(predictions),predictions.length,pc,Matrices.flatten(labels),labels.length,lc,context.handle(),out,e.pointer(),e.capacity()));return out.getValue();}
}
